+package com.example.contact;
+
+import java.util.ArrayList;
+import java.util.List;
+import org.springframework.stereotype.Service;
+
+/** In-memory history shared by successive visits to the contact view. */
+@Service
+public class MessageStore {
+    public record SentMessage(String name, String email, String phone, String message) {}
+
+    private final List<SentMessage> messages = new ArrayList<>();
+
+    public synchronized void add(SentMessage message) {
+        messages.addFirst(message);
+    }
+
+    public synchronized List<SentMessage> all() {
+        return List.copyOf(messages);
+    }
+}
